UPDATE task_queue
SET status = 'claimed',
    lock_owner = #{owner},
    lock_expire_at = #{lockExpireAt},
    updated_at = #{now}
WHERE id IN

    #{id}

  AND status = 'pending'
  AND next_retry_at <= #{now}

UPDATE task_queue
SET status = 'done',
    lock_owner = NULL,
    lock_expire_at = NULL,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'claimed'
  AND lock_owner = #{owner}

UPDATE task_queue
SET status = 'dead',
    last_error = #{error},
    lock_owner = NULL,
    lock_expire_at = NULL,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'claimed'
  AND lock_owner = #{owner}

UPDATE task_queue
SET status = 'done',
    lock_owner = NULL,
    lock_expire_at = NULL,
    updated_at = #{now}
WHERE task_type = #{taskType}
  AND biz_no = #{bizNo}
  AND status = 'pending'
